protected void onCreate(android.os.Bundle savedInstanceState) {
    super.onCreate(savedInstanceState);
}

@Override // android.support.v4.app.FragmentActivity, android.app.Activity
protected void onResume() {
    super.onResume();
    setContentView(edu.ksu.cs.benign.R.layout.activity_main);
    java.lang.String data = null;
    android.webkit.WebView webView = (android.webkit.WebView) findViewById(edu.ksu.cs.benign.R.id.webview1);
    webView.setWebViewClient(new android.webkit.WebViewClient());
    android.webkit.WebSettings webSettings = webView.getSettings();
    webSettings.setAllowFileAccess(true);
    webSettings.setAllowUniversalAccessFromFileURLs(true);
    webSettings.setJavaScriptEnabled(true);
    try {
        data = readFile(getAssets().open("demo.html"));
        android.util.Log.d("loadData", data);
    } catch (java.io.IOException e) {
        e.printStackTrace();
    }
    webView.loadDataWithBaseURL("file:///www.google.com", data, "text/html", "utf-8", null);
}
